entries[144235] = { ["name"] = "Zauberstab der Bannung", ["text"] = "Questgegenstand\nBenutzen: Entfernt auf der Terrasse der Tränen magische Effekte von Gegnern in der Nähe. (5 Sek. Abklingzeit)" }
entries[144236] = { ["name"] = "Mantel des Meisterassassinen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nSchulter Leder\n6 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 120 / 120\nKlassen: Schurke\nAnlegen: Erhöht in Verstohlenheit und 5 Sek. nach dem Verlassen der Verstohlenheit Eure kritische Trefferchance um 100%.\n\"Fürchtet nicht das, was Ihr sehen könnt. Fürchtet das, was Ihr nicht kommen seht. – Mathias Shaw, SI:7\"\nVerkaufspreis:" }
entries[144238] = { ["name"] = "Uralte Knochen", ["text"] = "Questgegenstand\n\"Nicht identifizierte und undatierte Überreste.\"" }
entries[144239] = { ["name"] = "Der kaiserliche Kondensator", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBrust Leder\n8 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 6.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 200 / 200\nKlassen: Mönch\nAnlegen: Chi verbrauchende Fähigkeiten erhöhen den Schaden Eures nächsten Einsatzes von 'Knisternder Jadeblitz' um 100% und verringern seine Kosten um 5%. Bis zu 20-mal stapelbar.\n\"Gestohlen vom hohen Hüter Ra-den, dem gefallenen Hüter der Stürme.\"\nVerkaufspreis:" }
entries[144240] = { ["name"] = "Verwüstete Vorräte", ["text"] = "Questgegenstand\n\"Von nur wenig Teufelsschleim bedeckt. Vermutlich noch in Ordnung.\"" }
entries[144241] = { ["name"] = "Teufelserfüllte Überreste", ["text"] = "Questgegenstand\n\"Teufelsenergien haben diesen Knochen schwer zugesetzt.\"" }
entries[144242] = { ["name"] = "X'onis Umarmung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHände Leder\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Druide\nAnlegen: 'Eisenborke' klingt 20% schneller ab. Außerdem erhalten von Eurer 'Eisenborke' geschützte Verbündete zusätzlich 75% der Heilung all Eurer Effekte von 'Verjüngung', die derzeit aktiv sind.\n\"X'onis bloße Präsenz erfüllte ihre Verbündeten mit Lebensfreude. Obwohl sie eine der mächtigsten Druidinnen aller Zeiten war, erlernte sie viele ihrer Fertigkeiten von der legendären Priesterin Phyrix.\"\nVerkaufspreis:" }
entries[144243] = { ["name"] = "Arsenal: Waffen des bösartigen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt die Vorlagen des Waffensets des bösartigen Gladiators." }
entries[144244] = { ["name"] = "Kam Xi'raff", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nKopf Stoff\n4 Rüstung\n+5 Intelligenz\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 6.\nHaltbarkeit 120 / 120\nKlassen: Priester\nAnlegen: Verringert die Kosten Eurer Heilzauber um 3%.\nAnlegen: Der Einsatz von 'Zorn des Lichts' verringert die Manakosten Eurer Zauber 1 Sek. lang um 50%. Hält 1 Sek. länger für jeden Verbündeten an, der mit Eurer 'Abbitte' belegt ist.\n\"Benannt nach einem unvergleichlichen Priester, dessen Namen niemand je aussprechen konnte.\"\nVerkaufspreis:" }
entries[144245] = { ["name"] = "Arsenal: Waffen des tyrannischen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt die Vorlagen des Waffensets des tyrannischen Gladiators." }
entries[144246] = { ["name"] = "Arsenal: Waffen des tyrannischen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt die Vorlagen des Waffensets des tyrannischen Gladiators." }
entries[144247] = { ["name"] = "Rammals Hintergedanke", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHände Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 70 / 70\nKlassen: Priester\nAnlegen: Wenn 'Gebet der Besserung' heilt, belegt es den Verbündeten 10 Sek. lang mit 'Rammals Hintergedanke' und erhöht damit den Effekt Eures nächsten Einsatzes von 'Blitzheilung', 'Heilung' oder 'Segenswort: Epiphanie', das Ihr auf ihn wirkt, um 20%.\n\"Nachdem Rammal seine wahre Gestalt enthüllte, erkannte Verius schon bald seine Beweggründe.\"\nVerkaufspreis:" }
entries[144248] = { ["name"] = "Arsenal: Waffen des stolzen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt die Vorlagen des Waffensets des stolzen Gladiators." }
entries[144249] = { ["name"] = "Archimondes wiedergeborener Hass", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 [Beweglichkeit oder Stärke oder Intelligenz]\n+ 4 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 4.\nBenutzen: Verleiht Euch 10 Sek. lang einen Absorptionsschild, der 30% Eurer maximalen Gesundheit entspricht. Wenn der Schild verbraucht ist oder abläuft, wird 75% der absorbierten Menge gleichmäßig unter Gegnern in der Nähe als Schaden aufgeteilt. (1 Min, 15 Sek. Abklingzeit)\n\"Archimonde der Entweiher, Heerführer der Legionsarmee, kontrolliert grenzenlose Mächte und vernichtete zahllose Welten in der Unendlichkeit der Universen.\"\nVerkaufspreis:" }
entries[144250] = { ["name"] = "Arsenal: Waffen des stolzen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt die Vorlagen des Waffensets des stolzen Gladiators." }
entries[144251] = { ["name"] = "Arsenal: Waffen des erbitterten Gladiators", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt die Vorlagen des Waffensets des erbitterten Gladiators." }
