entries[144255] = { ["name"] = "Ausgelaugte Teufelskristalle", ["text"] = "Questgegenstand\n\"Die Teufelsenergie ist entschwunden.\"" }
entries[144256] = { ["name"] = "Teufelskristalle", ["text"] = "Questgegenstand\n\"Strahlt Teufelsenergie aus.\"" }
entries[144258] = { ["name"] = "Velens Blick in die Zukunft", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 [Beweglichkeit oder Stärke oder Intelligenz]\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\nBenutzen: Erhöht 10 Sek. lang jegliche verursachte Heilung um 15% und leitet 50% der überschüssigen Heilung auf bis zu 3 verletzte Verbündete in der Nähe um. (1 Min, 15 Sek. Abklingzeit)\n\"Velen der Zeitlose, unter seinem Volk auch als 'Der Prophet' verehrt, ist mit der Gabe des Sehens gesegnet. Unter der behütenden Hand des Lichts führte er die Draenei über 25000 Jahre lang an.\"\nVerkaufspreis:" }
entries[144259] = { ["name"] = "Kil'jaedens brennender Wunsch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 [Beweglichkeit oder Stärke oder Intelligenz]\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\nBenutzen: Feuert einen Vortex der Zerstörung, der Euer aktuelles Ziel verfolgt. Wenn er das Ziel trifft, explodiert er, trifft kritisch und fügt allen Gegnern innerhalb von 10 Metern ( 32 * 200 / 100) Feuerschaden zu. (1 Min, 15 Sek. Abklingzeit)\n\"Kil'jaeden der Betrüger, oberster General der Brennenden Legion, hat ein simples Streben: Alles Leben und jegliche Magie verzehren, der Legion jedes Volk im Universum einverleiben, jeden Widerstand auslöschen und die gesamte Schöpfung vernichten.\"\nVerkaufspreis:" }
entries[144260] = { ["name"] = "Eiszeit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nSchulter Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 120 / 120\nKlassen: Magier\nAnlegen: Eure 'Gefrorene Kugel' explodiert in einer 'Frostnova', die (150% der Zaubermacht) Schaden verursacht.\n\"Sie scheinen immer ein magisches Ass im Ärmel zu haben.\"\nVerkaufspreis:" }
