entries[144266] = { ["name"] = "Zertrümmertes Horn eines Zornwächters", ["text"] = "Wird beim Aufheben gebunden\nVerkaufspreis:" }
entries[144267] = { ["name"] = "Blutiger Axtkopf der Horde", ["text"] = "Wird beim Aufheben gebunden\nVerkaufspreis:" }
entries[144268] = { ["name"] = "Infanterieklinge der Allianz", ["text"] = "Wird beim Aufheben gebunden\nVerkaufspreis:" }
entries[144269] = { ["name"] = "Leerer Seelensplitter", ["text"] = "Wird beim Aufheben gebunden\nVerkaufspreis:" }
