entries[144271] = { ["name"] = "Sengende Klaue einer Ausgeburt", ["text"] = "Wird beim Aufheben gebunden\nVerkaufspreis:" }
entries[144272] = { ["name"] = "Siegel des Heldenmuts", ["text"] = "Wird beim Aufheben gebunden\nVerkaufspreis:" }
entries[144273] = { ["name"] = "Maraads letzter Atemzug", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 [Stärke oder Intelligenz]\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 2.\nKlassen: Paladin\nAnlegen: Die Heilung von 'Licht der Morgendämmerung' bewirkt, dass Euer nächster Einsatz von 'Licht des Märtyrers' zusätzlich Eure 'Flamme des Glaubens' heilt. Jeder von 'Licht der Morgendämmerung' geheilte Verbündete erhöht die Heilung von 'Licht des Märtyrers' um 10%.\n\"Im Licht sind wir eins.\"\nVerkaufspreis:" }
entries[144274] = { ["name"] = "Gravitationsspirale", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nKopf Stoff\n4 Rüstung\n+5 Intelligenz\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 6.\nHaltbarkeit 120 / 120\nKlassen: Magier\nAnlegen: Verleiht Eurer Fähigkeit 'Hervorrufung' 1 zusätzliche Aufladung.\n\"Die Existenz und Rekombination verschiedener Kräfte und Energien erschafft oft mächtige Manawirbel.\"\nVerkaufspreis:" }
entries[144275] = { ["name"] = "Saruans Entschlossenheit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nKopf Platte\n13 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nErhöht Eure Tempowertung um + 4.\n+ 6 Vielseitigkeit\nHaltbarkeit 120 / 120\nKlassen: Paladin\nAnlegen: 'Licht des Beschützers' erhält 1 zusätzliche Aufladung und klingt 10% schneller ab.\n\"Entgegen der Lügen von Matis dem Grausamen blieb Saruan bis zu seinem Abschied vom Licht standhaft.\"\nVerkaufspreis:" }
entries[144276] = { ["name"] = "Sack mit Heilsporen", ["text"] = "Benutzen: Heilt Fshoo 10 Sek. lang um 7500 . Kanalisiert.\nBenötigt Glühkappenfest" }
entries[144277] = { ["name"] = "Ambossgehärtete Gelenkbänder", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Leder\n4 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 70 / 70\nKlassen: Mönch\nAnlegen: Wenn Ihr ausweicht oder ein Gegner Euch verfehlt, wird die verbleibende Abklingzeit Eurer Gebräue jedes Mal um 1.0 Sek. verringert. (1s Abklingzeit)\n\"Einst gehörten sie Wei Schnellbräu, Meister der Brau- und Schmiedekunst.\"\nVerkaufspreis:" }
entries[144279] = { ["name"] = "Größenwahn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nSchulter Leder\n6 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 120 / 120\nKlassen: Dämonenjäger\nAnlegen: Verringert die verbleibende Abklingzeit von 'Metamorphose' pro 30 verbrauchtem Jähzorn um 1 Sek.\n\"Mehr Macht... um jeden Preis.\"\nVerkaufspreis:" }
entries[144280] = { ["name"] = "Todesmarsch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nKopf Platte\n13 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 6.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 120 / 120\nKlassen: Todesritter\nAnlegen: 'Todesstoß' und 'Todesmantel' verursachen 10% mehr Schaden und verringern die verbleibende Abklingzeit von [ Entweihen : 'Entweihen' / 'Tod und Verfall'] um 2.0 Sek.\n\"In dieser Welt ist nichts gewiss, außer dem Tod.\"\nVerkaufspreis:" }
entries[144281] = { ["name"] = "Schädelblumes Hämostase", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nSchulter Platte\n12 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\nErhöht Eure Tempowertung um + 4.\n+ 3 Vielseitigkeit\nHaltbarkeit 120 / 120\nKlassen: Todesritter\nAnlegen: 'Siedendes Blut' erhöht den verursachten Schaden sowie die hervorgerufene Heilung Eures nächsten Einsatzes von 'Todesstoß' um 20%. Bis zu 5-mal stapelbar. (500ms Abklingzeit)\n\"Blut um Blut.\"\nVerkaufspreis:" }
entries[144282] = { ["name"] = "Schlägerharnisch", ["text"] = "Questgegenstand\nBenutzen: Beschwört einen unterjochten Bestrafer als Reittier." }
entries[144283] = { ["name"] = "Muschelschalenherz", ["text"] = "\"Ein mehr oder weniger herzförmiges Bruchstück einer Winterflossenmuschel.\"\nVerkaufspreis:" }
entries[144284] = { ["name"] = "Zerkautes Stück Treibholz", ["text"] = "\"Es sieht Euch ein bisschen ähnlich.\"\nVerkaufspreis:" }
entries[144285] = { ["name"] = "Seetangkunstwerk", ["text"] = "\"Mehrere Fetzen Seetang, die an einem flachen Stein befestigt wurden.\"\nVerkaufspreis:" }
entries[144286] = { ["name"] = "Halber Fisch", ["text"] = "\"Eure Kaulquappe hat die Hälfte ihres Mittagessens für Euch aufgespart.\"\nVerkaufspreis:" }
entries[144287] = { ["name"] = "Nasser Stein", ["text"] = "\"Eure Kaulquappe sprang vor Aufregung auf und ab, als sie Euch dieses Geschenk überreichte.\"\nVerkaufspreis:" }
entries[144288] = { ["name"] = "Flossevoll funkelnder Sand", ["text"] = "\"Mit stolzgeschwellter Brust überreichte Euch Eure Kaulquappe diesen Sand. Sie muss tief getaucht sein, um ihn zu bekommen.\"\nVerkaufspreis:" }
entries[144289] = { ["name"] = "Winterflossenmatschkuchen", ["text"] = "\"Eure Kaulquappe starrte Euch mit erwartungsvoll aufgerissenen Augen an, als sie Euch diese liebevoll zubereitete Mahlzeit überreichte.\"\nVerkaufspreis:" }
entries[144290] = { ["name"] = "Winterflossenperle", ["text"] = "\"Das ist... eine unerwartet hübsche Perle.\"\nVerkaufspreis:" }
entries[144291] = { ["name"] = "Kaulquappengeschenk", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[144292] = { ["name"] = "Geist der Finsterflamme", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHände Leder\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n+ 4 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Dämonenjäger\nAnlegen: Euer 'Flammendes Brandmal' heilt Euch jetzt um 100% des verursachten Schadens und jeder von Eurem 'Zeichen der Flamme' getroffene Gegner erhöht den direkten Schaden Eures nächsten Einsatzes von 'Flammendes Brandmal' um 15%. Bis zu 15-mal stapelbar.\n\"Der Drache der Finsterflamme kann den Besitzer zuweilen übel zurichten. Doch wer seine Macht zu kontrollieren vermag, dem verleiht er Kräfte jenseits jeder Vorstellungskraft.\"\nVerkaufspreis:" }
entries[144293] = { ["name"] = "Eisiger Kern der Gemahlin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBeine Platte\n16 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 6.\nHaltbarkeit 145 / 145\nKlassen: Todesritter\nAnlegen: Verringert die Abklingzeit von 'Furor des Frostwyrms' um 50% und friert alle getroffenen Gegner 3 Sek. lang an Ort und Stelle fest.\n\"Und im Moment ihres Todes... ertranken Sindragosas letzte Gedanken in Verbitterung, Hass und Rachsucht.\"\nVerkaufspreis:" }
entries[144294] = { ["name"] = "Gepanzertes Rossgeschirr", ["text"] = "Questgegenstand\n\"Dieses Geschirr suchte Grayson vermutlich.\"" }
entries[144295] = { ["name"] = "Die Dame und das Kind", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nSchulter Leder\n6 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 4.\nHaltbarkeit 120 / 120\nKlassen: Druide\nAnlegen: 'Mondfeuer' verursacht 20% mehr Schaden und trifft einen weiteren Gegner in der Nähe innerhalb von 15 Metern um das Ziel.\n\"Nachdem er lange und unbeirrt in sein Innerstes blickte, lernte Erzdruide Thom'acos die Macht der Zwillingsmonde zu imitieren.\"\nVerkaufspreis:" }
entries[144296] = { ["name"] = "Kroksys Schlüssel", ["text"] = "Einzigartig\nBenutzen: Entfernt ein schweres Rüstungsset.\nVerkaufspreis:" }
entries[144297] = { ["name"] = "Talisman des Sieges", ["text"] = "Wird beim Aufheben gebunden\nVerkaufspreis:" }
entries[144298] = { ["name"] = "S.E.L.F.I.E.-Kamera", ["text"] = "Wird beim Aufheben gebunden\nDauer: 1 tag (Realzeit)\nBenutzen: Setzt Euch perfekt in Szene und schießt ein Selfie! (2 Sek. Abklingzeit)\n\"Wegwerfartikel.\"" }
entries[144299] = { ["name"] = "Beschädigte Statuette", ["text"] = "Questgegenstand\n\"Aus demselben Gestein gefertigt, das überall in den umliegenden Ruinen zu finden ist.\"" }
entries[144300] = { ["name"] = "Unbesehnter Bogenrücken", ["text"] = "Questgegenstand\n\"Komplexe Runen wurden in das Holz geätzt.\"" }
entries[144301] = { ["name"] = "Kunstvoll verzierte Brosche", ["text"] = "Questgegenstand\n\"Von den Händen eines Meisters hergestellt.\"" }
entries[144302] = { ["name"] = "Juwelenbesetzter Kelch", ["text"] = "Questgegenstand\n\"Mit zahllosen Edelsteinen verschiedener Größen und Farben verziert.\"" }
entries[144303] = { ["name"] = "Gyrostabilisator MK II", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHände Kette\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Jäger\nAnlegen: Euer 'Gezielter Schuss' gewährt Euch 'Gyrostabilisierung'. Erhöht die kritische Trefferchance Eures nächsten Einsatzes von 'Gezielter Schuss' um 15% und er kann aus der Bewegung heraus eingesetzt werden.\n\"Wie? Durch statische Aufrechterhaltung des dynamischen Drehimpulsvektors natürlich! Dumme Frage.\"\nVerkaufspreis:" }
entries[144304] = { ["name"] = "Hals - Mal des Meisters", ["text"] = "Benutzen: Eine Halskette dauerhaft verzaubern, sodass die Meisterschaft um 7 erhöht wird. Kann nicht auf Gegenstände über Stufe 376 angewandt werden.\nVerkaufspreis:" }
