entries[144306] = { ["name"] = "Hals - Mal der Schnellen", ["text"] = "Benutzen: Eine Halskette dauerhaft verzaubern, sodass das Tempo um 7 erhöht wird. Kann nicht auf Gegenstände über Stufe 376 angewandt werden.\nVerkaufspreis:" }
entries[144307] = { ["name"] = "Hals - Mal der Tödlichen", ["text"] = "Benutzen: Eine Halskette dauerhaft verzaubern, sodass der kritische Trefferwert um 7 erhöht wird. Kann nicht auf Gegenstände über Stufe 376 angewandt werden.\nVerkaufspreis:" }
entries[144308] = { ["name"] = "Formel: Hals - Mal des Meisters", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man die Verzauberung 'Mal des Meisters' durchführt.\nEine Halskette dauerhaft verzaubern, sodass die Meisterschaft um 7 erhöht wird. Kann nicht auf Gegenstände über Stufe 376 angewandt werden.\nBenötigt Verzauberkunst der Verheerten Inseln (1)" }
