entries[144322] = { ["name"] = "Zerrissenes Gemälde", ["text"] = "Questgegenstand\n\"Die einst leuchtenden Farben sind mit der Zeit verblasst.\"" }
entries[144323] = { ["name"] = "Seidene Pantoffeln", ["text"] = "Questgegenstand\n\"Handgenäht und streichelzart.\"" }
entries[144324] = { ["name"] = "Angelaufenes Band", ["text"] = "Questgegenstand\n\"Zwei verschiedene Initialen wurden in das weiche Metall graviert.\"" }
entries[144325] = { ["name"] = "Kristalldolch", ["text"] = "Questgegenstand\n\"Aus Sand und Sturm geschmiedet.\"" }
entries[144326] = { ["name"] = "Der Mantel des Alphas", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nSchulter Kette\n8 Rüstung\n+4 Beweglichkeit\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 120 / 120\nKlassen: Jäger\nAnlegen: 'Stachelpfeil' erhöht den verursachten Schaden Eurer Begleiter 8 Sek. lang um 5%.\n\"Zusammengeflickt aus den Pelzen ungehorsamer Haustiere.\"\nVerkaufspreis:" }
entries[144328] = { ["name"] = "Segen des Konstrukteurs", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Eine Schulterrüstung dauerhaft mit 'Segen des Konstrukteurs' verzaubern, sodass sie es dem Träger gestattet, von den Leichen seiner Gegner Ersatzteilbehälter zu plündern. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:" }
entries[144329] = { ["name"] = "Gehärtetes Teufelsglas", ["text"] = "Handwerksmaterial\n\"Kann in Ersatzteilbehältern gefunden werden, die von Spielercharakteren mit der Verzauberung 'Segen des Konstrukteurs' erbeutet werden können.\"\nVerkaufspreis:" }
entries[144330] = { ["name"] = "Ersatzteilbehälter", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält Ingenieursmaterialien der Verheerten Inseln. Kann von Spielercharakteren mit der Verzauberung 'Segen des Konstrukteurs' erbeutet werden.\"\n<Zum Öffnen rechtsklicken>" }
entries[144331] = { ["name"] = "Schneidiger Schädelstrahler", ["text"] = "Wird beim Anlegen gebunden\nKopf Stoff\n4 Rüstung\n+5 Intelligenz\n+7 Ausdauer\nHaltbarkeit 100 / 100\nBenutzen: Feuert ein Geschoss auf Euer aktuelles Ziel ab. (5 Min Abklingzeit)\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:" }
entries[144332] = { ["name"] = "Derber Schädelstrahler", ["text"] = "Wird beim Anlegen gebunden\nKopf Leder\n6 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nHaltbarkeit 100 / 100\nBenutzen: Feuert ein Geschoss auf Euer aktuelles Ziel ab. (5 Min Abklingzeit)\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:" }
