entries[144343] = { ["name"] = "Bauplan: Reaves' aufladbare Batterie", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung von Reaves' aufladbarer Batterie.\nStellt Reaves' aufladbare Batterie her.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\n\nReaves' aufladbare Batterie\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Beschwört Reaves. (30 Min Abklingzeit)\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:\nBenötigt Reaves' Batterie , Leysteinerz (75), Blut von Sargeras (15)" }
