entries[144346] = { ["name"] = "Gabe des Tierpflegers", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Eine Schulterrüstung dauerhaft mit 'Ernter' verzaubern, sodass sie es dem Träger gestattet, von den Leichen seiner Gegner eine Handvoll Haustierleckerlis zu plündern. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:" }
