entries[144354] = { ["name"] = "Feuerrote Zerfledderer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBeine Leder\n7 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 6.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 145 / 145\nKlassen: Druide\nAnlegen: Erhöht sämtlichen verursachten Schaden um 3%.\nAnlegen: Nach dem Einsatz von 'Ashamanes Raserei' kostet Euer nächstes 'Zerfleddern' keine Energie, verursacht 500% mehr Schaden und trifft 2 zusätzliche Gegner in der Nähe des Ziels.\n\"Katzen sind launisch. Wenn sie zu Euch kommen, ist es wunderbar. Doch wenn Ihr zu ihnen geht, läuft das nicht immer gut.\"\nVerkaufspreis:" }
entries[144355] = { ["name"] = "Pyrotexzündgewebe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHände Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Magier\nAnlegen: 'Phönixflammen' verringern die verbleibende Abklingzeit von 'Einäschern' um 9 Sek.\n\"Natürlich könnt Ihr Feuer mit Feuer bekämpfen. Man kann alles mit Feuer bekämpfen.\"\nVerkaufspreis:" }
entries[144357] = { ["name"] = "Corins Schlüssel", ["text"] = "Einzigartig\nBenutzen: Entfernt ein schweres Rüstungsset.\nVerkaufspreis:" }
entries[144358] = { ["name"] = "Asche zu Staub", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nSchulter Platte\n12 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 120 / 120\nKlassen: Paladin\nAnlegen: Erhöht 6 Sek. lang Euren verursachten Schaden gegen Gegner, die von Eurer 'Aschewelle' getroffen wurden um 15%.\n\"Das Feuer wäscht die Seele rein und übrig bleibt ein Mund voll...\"\nVerkaufspreis:" }
entries[144361] = { ["name"] = "Knochenschürze des Schlächters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBrust Kette\n12 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 6.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 200 / 200\nKlassen: Jäger\nAnlegen: [ Mungobiss : 'Mungobiss' / 'Raptorstoß'] erhöht den Schaden Eures nächsten Einsatzes von [ Schlachten : 'Schlachten' / 'Zerlegen'] um 10%. Bis zu 10-mal stapelbar.\n\"Ah... Frischfleisch...\"\nVerkaufspreis:" }
