entries[144364] = { ["name"] = "Ernten und Säen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 Intelligenz\n+4 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 4.\nKlassen: Hexenmeister\nAnlegen: Erhöht sämtlichen verursachten Schaden um 3%.\nAnlegen: 'Seelen ernten' hält pro verschlungener Seele 1.5 Sek. länger an.\n\"Wenn man erntet was man sät... nun, dann mache ich mich wohl besser auf den Weg.\"\nVerkaufspreis:" }
