entries[144369] = { ["name"] = "Lehren der Raumzeit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nSchulter Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 120 / 120\nKlassen: Hexenmeister\nAnlegen: Erhöht sämtlichen verursachten Schaden um 3%.\nAnlegen: Erhöht jeglichen verursachten Schaden um 10%, solange ein Dimensionsriss offen ist.\n\"Das Anwachsen von Chaos mit der Zeit unterscheidet die Vergangenheit von der Zukunft, indem es der Zeit eine Richtung gibt. – Hawking, Professor der Raumzeitstudien\"\nVerkaufspreis:" }
