entries[144394] = { ["name"] = "Tylarr Gronnden", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick Tylarr Gronnden beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Rang 3 in Bizmos Boxbar.\nBenötigt Rang 3 in der Shlae'gararena." }
entries[144395] = { ["name"] = "Übersicht der Artefaktforschung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lesen, um neues Wissen über Euer Artefakt zu erlangen und die Rate zu erhöhen, mit der Ihr Artefaktmacht erlangt. Kann Euer Artefaktwissen nur bis Stufe 15 erhöhen.\n\"Ein Überblick der Notizen über viele der großen Waffen, die eine Rolle in der Geschichte Azeroths spielten.\"" }
