entries[144432] = { ["name"] = "Eichenherz' Holzkopf", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nKopf Leder\n6 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\n+ 4 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 6.\nHaltbarkeit 120 / 120\nKlassen: Druide\nAnlegen: 'Baumrinde' erzeugt sofort 45 Wut sowie im Verlauf von 3 Sek. zusätzlich 30 Wut.\n\"Mit meinem Stamm ramm ich Euch in den Schlamm...\"\nVerkaufspreis:" }
