entries[144436] = { ["name"] = "Vergessene Legende von Odyn", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lest dies vor Odyns Runentafel in der Himmelsfeste, um eine weitere Legende von Odyn freizuschalten.\n\"Die Schriftrolle ist alt, doch die Runen leuchten golden wie die auf den Runentafeln in der Himmelsfeste.\"" }
