entries[144438] = { ["name"] = "Zeks Exterminatus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 Intelligenz\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 2.\nKlassen: Priester\nAnlegen: Der Schaden Eures Zaubers 'Schattenwort: Schmerz' hat eine Chance, den Schaden Eures nächsten Einsatzes von 'Schattenwort: Tod' um 100% zu erhöhen und den Zauber auf alle Ziele anwendbar zu machen, ungeachtet ihrer Gesundheit.\n\"Ihr denkt, ich fürchte den Tod? Ich bin so oft gestorben, der Tod ist Routine für mich. Könnt Ihr das auch behaupten?\"\nVerkaufspreis:" }
entries[144439] = { ["name"] = "Herausforderungskarte: Klump", ["text"] = "Rang 8\nWird beim Aufheben gebunden\nEinzigartig: Herausforderungskarte (1)\n\"Einem Vertreter der Kampfgilde überreichen, um Klump herauszufordern. Ihr könnt nur jeweils eine Herausforderungskarte besitzen.\"\nVerkaufspreis:" }
